import json
import sys


def main(argv):
    if not argv:
        print("error: missing config file path", file=sys.stderr)
        return 2
    try:
        with open(argv[0]) as stream:
            config = json.load(stream)
    except (OSError, ValueError) as exc:
        print(f"error: could not read config file {argv[0]}: {exc}", file=sys.stderr)
        return 2
    if not isinstance(config, dict) or "name" not in config:
        print("error: config must be a JSON object with a 'name' key", file=sys.stderr)
        return 2
    print(config["name"])
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
